const InHouseSurveyGuarantor = ({ open, onClose }) => {
  const columnDefs = [
    {
      field: "No",
      headerName: "No",
      width: 200,
      sortable: true,
      resizable: true,
      pinned: "left",
    },
    {
      field: "Full Name",
      headerName: "Full Name",
      width: 200,
      sortable: true,
      resizable: true,
    },
    {
      field: "NRC",
      headerName: "NRC",
      width: 200,
      sortable: true,
      resizable: true,
    },
    {
      field: "NRC State/Division",
      headerName: "NRC State/Division",
      width: 200,
      sortable: true,
      resizable: true,
    },
    {
      field: "NRC District/Township",
      headerName: "NRC District/Township",
      width: 200,
      sortable: true,
      resizable: true,
    },
  ];
  return (
    <Dialog
      sx={{ "& .MuiDialog-paper": { width: "80%" } }}
      maxWidth="lg"
      open={open}
    >
      <DialogTitle
        id="scroll-dialog-title"
        variant="h5"
        sx={{ color: "#1890ff" }}
      >
        Guarantor Information List
      </DialogTitle>
      <DialogContent dividers>
        <Table
          rowSelection={"single"}
          columnDefs={columnDefs}
          name="InHouseSurveyGuarantor"
          rowData={rows}
          rowKey="No"
          defaultColDef={{
            flex: 1,
          }}
          agThemeStyle={{
            height: "calc(100vh - 220px)",
          }}
        />
      </DialogContent>
      <DialogActions>
        <Button autoFocus onClick={onClose}>
          Cancel
        </Button>
        <Button onClick={onClose}>Ok</Button>
      </DialogActions>
    </Dialog>
  );
};

export default React.memo(InHouseSurveyGuarantor);
